#!/usr/bin/env node
/** Apply the system DayNight theme to the Android project generated by `npx cap add android`. */
import fs from 'node:fs';
import path from 'node:path';

const root = process.cwd();
const valuesDir = path.join(root, 'android/app/src/main/res/values');
const nightDir = path.join(root, 'android/app/src/main/res/values-night');
const stylesPath = path.join(valuesDir, 'styles.xml');
const manifestPath = path.join(root, 'android/app/src/main/AndroidManifest.xml');

if (!fs.existsSync(stylesPath) || !fs.existsSync(manifestPath)) {
  throw new Error('Run `npx cap add android` before configuring the Android theme.');
}

const setItems = (style, items) => {
  for (const [name, value] of Object.entries(items)) {
    const re = new RegExp(`<item\\s+name=["']${name}["'][^>]*>[\\s\\S]*?<\\/item>`);
    const next = `<item name="${name}">${value}</item>`;
    style = re.test(style) ? style.replace(re, next) : style.replace('</style>', `        ${next}\n    </style>`);
  }
  return style;
};

function updateStyle(xml, name, parent, items) {
  const re = new RegExp(`<style\\s+name=["']${name}["'][^>]*>[\\s\\S]*?<\\/style>`);
  if (!re.test(xml)) {
    const style = setItems(`<style name="${name}" parent="${parent}">\n    </style>`, items);
    return xml.replace('</resources>', `    ${style}\n</resources>`);
  }
  return xml.replace(re, (old) => {
    let style = old.replace(/parent=["'][^"']*["']/, `parent="${parent}"`);
    if (!/parent=/.test(style)) style = style.replace(`<style name="${name}"`, `<style name="${name}" parent="${parent}"`);
    return setItems(style, items);
  });
}

const baseItems = {
  windowActionBar: 'false',
  windowNoTitle: 'true',
  'android:statusBarColor': '#0b4fb3',
  'android:navigationBarColor': '#0b4fb3',
  'android:windowLightStatusBar': 'true',
  'android:windowLightNavigationBar': 'true',
};
const dayNightParent = 'Theme.AppCompat.DayNight.NoActionBar';

let styles = fs.readFileSync(stylesPath, 'utf8');
styles = updateStyle(styles, 'AppTheme.NoActionBar', dayNightParent, baseItems);
// Android 12+ always shows a system launch window. Keep it neutral and icon-free instead
// of showing a large, prolonged branded splash while the WebView starts.
const drawableDir = path.join(root, 'android/app/src/main/res/drawable');
fs.mkdirSync(drawableDir, { recursive: true });
fs.writeFileSync(path.join(drawableDir, 'launch_empty.xml'), '<vector xmlns:android="http://schemas.android.com/apk/res/android" android:width="1dp" android:height="1dp" android:viewportWidth="1" android:viewportHeight="1"><path android:fillColor="#00000000" android:pathData="M0,0h1v1h-1z"/></vector>\n');
styles = updateStyle(styles, 'AppTheme.NoActionBarLaunch', 'Theme.SplashScreen', {
  'android:background': '#14171b',
  windowSplashScreenBackground: '#14171b',
  windowSplashScreenAnimatedIcon: '@drawable/launch_empty',
  postSplashScreenTheme: '@style/AppTheme.NoActionBar',
});
fs.writeFileSync(stylesPath, styles);

fs.mkdirSync(nightDir, { recursive: true });
const nightPath = path.join(nightDir, 'styles.xml');
let night = fs.existsSync(nightPath) ? fs.readFileSync(nightPath, 'utf8') : '<resources>\n</resources>\n';
night = updateStyle(night, 'AppTheme.NoActionBar', dayNightParent, {
  ...baseItems,
  'android:statusBarColor': '#1b1e22',
  'android:navigationBarColor': '#101215',
  'android:windowLightStatusBar': 'false',
  'android:windowLightNavigationBar': 'false',
});
fs.writeFileSync(nightPath, night);

let manifest = fs.readFileSync(manifestPath, 'utf8');
// Opt in to Android's modern system-back dispatch for gesture navigation.
if (!manifest.includes('android:enableOnBackInvokedCallback=')) {
  manifest = manifest.replace('<application', '<application android:enableOnBackInvokedCallback="true"');
}
// Let Android recreate BridgeActivity on a system light/dark switch so WebView gets the new isLightTheme.
manifest = manifest.replace(/android:configChanges="([^"]+)"/g, (match, value) => {
  const next = value.split('|').filter((part) => part !== 'uiMode').join('|');
  return match.replace(value, next);
});
fs.writeFileSync(manifestPath, manifest);

console.log('Android AppTheme now follows system light/dark and WebView prefers-color-scheme.');